# FIX: the special characters (the share arrow, the star, the collapse
# arrows, the tag placeholder icon) in the listing sheet came out as
# garbled text/boxes after the last script ran, instead of the actual
# star/arrow symbols. That happened because those symbols are made of
# multi-byte Unicode, and something between this script's text and your
# PowerShell session read them using the wrong character set before
# writing the files back out -- corrupting every special character in
# that file, not just the new share button (which is why the existing
# star button got scrambled too, even though nothing about it changed).
#
# This script fixes it for good: instead of writing the file text
# directly (which depends on PowerShell correctly guessing the right
# character encoding), it sends the exact bytes of each file pre-encoded
# as Base64 and writes them straight to disk with no text interpretation
# in between. That makes it immune to this whole class of bug, on any
# machine, regardless of language/region settings.
#
# Re-writes: components/ShareButton.js, components/ListingSheet.js,
# app/globals.css (all three exactly as intended). No database changes,
# no new dependency. Safe to re-run if something fails partway through.

$projectPath = "C:\Users\Bastian\Documents\WebDesign\SaleHop-app\salehopproject\salehop"

Write-Host "Moving into $projectPath ..." -ForegroundColor Cyan
if (-not (Test-Path $projectPath)) {
    Write-Host "ERROR: That folder doesn't exist. Double-check the path and edit it at the top of this script." -ForegroundColor Red
    exit 1
}
Set-Location $projectPath

if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
    Write-Host "ERROR: git isn't installed (or not on PATH)." -ForegroundColor Red
    exit 1
}

New-Item -ItemType Directory -Force -Path "components" | Out-Null
New-Item -ItemType Directory -Force -Path "app" | Out-Null

Write-Host "Writing components\ShareButton.js ..." -ForegroundColor Cyan
$b64 = ""
$bytes = [Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes("components\ShareButton.js", $bytes)

Write-Host "Writing components\ListingSheet.js ..." -ForegroundColor Cyan
$b64 = ""
$bytes = [Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes("components\ListingSheet.js", $bytes)

Write-Host "Writing app\globals.css ..." -ForegroundColor Cyan
$b64 = ""
$bytes = [Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes("app\globals.css", $bytes)

Write-Host "Staging, committing, and pushing ..." -ForegroundColor Cyan
git add .
git commit -m "Fix corrupted special characters (share/star/collapse icons) in the listing sheet"

if ($LASTEXITCODE -ne 0) {
    Write-Host ""
    Write-Host "If that failed with 'Please tell me who you are', run these two lines (with your info) then re-run this script:" -ForegroundColor Yellow
    Write-Host '  git config --global user.email "you@example.com"' -ForegroundColor Yellow
    Write-Host '  git config --global user.name "Your Name"' -ForegroundColor Yellow
    exit 1
}

git push

if ($LASTEXITCODE -eq 0) {
    Write-Host ""
    Write-Host "Done! Once Vercel finishes deploying, open a sale again -- the share arrow and the star should both show up as clean symbols, no boxes or garbled text." -ForegroundColor Green
} else {
    Write-Host ""
    Write-Host "The push didn't finish cleanly -- scroll up for git's error message and send it to me." -ForegroundColor Red
}
